def is_valid_ipv4(ip):
  parts = ip.split('.')
  if len(parts) != 4:
    return False
  for part in parts:
    if not part.isdigit():
      return False
    num = int(part)
    if num < 0 or num > 255:
      return False
  return True

def caesar_encrypt(text, shift):
    result = ""
    for char in text:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            result += chr((ord(char) - base + shift) % 26 + base)
        else:
            result += char
    return result

def caesar_decrypt(text, shift):
    return caesar_encrypt(text, -shift)
